from fractions import Fraction

def get_prime_factors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def solve():
    solutions = []
    for n in range(1, 4001):
        if n == 1:
            # f(1) = 0, so g(1) = 1*(0+1) = 1. g(1) = 2*1 is false.
            continue
        factors = get_prime_factors(n)
        s = Fraction(0)
        for p, a in factors.items():
            s += Fraction(a, p)

        if s == 1:
            solutions.append(n)
    return solutions

solutions = solve()
print(solutions)

